import functools
from typing import ForwardRef, Any, Dict
import inspect
from fastapi.dependencies.utils import get_typed_signature

# Define a class in a separate "module" (simulated by a dict)
class MyModel:
    pass

def wrapped_func(x: "MyModel"):
    return x

# Simulate a wrapper in a different module
def create_wrapper():
    @functools.wraps(wrapped_func)
    def wrapper(x: "MyModel"):
        return wrapped_func(x)
    return wrapper

def test_repro():
    wrapper = create_wrapper()
    try:
        sig = get_typed_signature(wrapper)
        print("Success!")
        print(f"Annotation: {sig.parameters['x'].annotation}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_repro()
