    # Test parameter annotation
    sig = get_typed_signature(wrapper)
    param_annotation = sig.parameters['x'].annotation
    print(f"Parameter Annotation: {param_annotation}")

    # Test return annotation
    return_annotation = get_typed_return_annotation(wrapper)
    print(f"Return Annotation: {return_annotation}")

    if param_annotation is MyModel and return_annotation is MyModel:
        print("Success!")
    else:
        print("Failure!")

if __name__ == "__main__":
    test_wrapped_func()

